ValidationRule.errorConditionFormula:
$Permission.GoldenCopy = false &&
AND (
$Profile.Name != 'System Administrator',
$Profile.Name != 'API Only',
$User.Country != TEXT (Country__c),
OR (
$User.Country = '',
NOT (
/* Owner country is present in allowed countries */
CONTAINS (
/* fetch allowed countries */
VLOOKUP(
$ObjectType.CountryGroup__c.Fields.Countries_Allowed__c,
$ObjectType.CountryGroup__c.Fields.Name,
$User.Country
),
TEXT (Country__c)
)
)
)
)
